import base64
import os

data = "data:image/jpeg;base64,"

if data.startswith("data:image"):
    data = data.split(",")[1]

# Fix padding
padding = len(data) % 4
if padding:
    data += "=" * (4 - padding)

try:
    img_data = base64.b64decode(data)
    with open(r"c:\Users\G\Desktop\cab\client\src\assets\dwarka-mandir.jpg", "wb") as f:
        f.write(img_data)
    print("Image saved successfully.")
except Exception as e:
    print(f"Error: {e}")
